// ===================== every owner picture is loaded and shown somewhere (urgent order, 8 Nov): preload, table themes, deck backs, card-list gallery =====================
// assetlist.js (generated by build.py) lists every file in media/ and models/. Pictures load in small idle batches after the first screen, so nothing slows the start.
// Where each family shows: goods (market row, 13px names) | djinn portraits (row + tap + drawer) | thieves (Cutpurse chip, thieves row, Card list) | card backs (deck piles by the rows, Card list)
// table-* (a different table each game, or the one unlocked in Story) | ui-* skins (seat chips, top bar, bubbles, buttons, panels) | end-win/end-lose (result card) | fx-sparkle (point pops) | camp-*, story-map, ui-node-*, ui-star-* (Story map) | glyph/icon/item/token/tile/meeple (board, hand, drawers)
const AS={n:0,done:false};
function assetsPreload(){const L=ASSET_FILES.slice();const next=()=>{const part=L.splice(0,6);part.forEach(f=>{const i=new Image();i.decoding='async';i.onload=i.onerror=()=>{AS.n++};i.src='media/'+f});if(L.length)setTimeout(next,140);else AS.done=true};next()}
if(document.readyState==='complete')setTimeout(assetsPreload,900);else addEventListener('load',()=>setTimeout(assetsPreload,900));
// a different table each game (the Story unlock still wins)
const TABLE_SET=['default','court','night','palace','workshop'];
(function(){const o=paintApply;paintApply=function(){o.apply(this,arguments);try{if(PAINT_ON&&G&&!unl('table')){const t=TABLE_SET[Math.abs(parseInt(G.seed,10)||0)%TABLE_SET.length];if(t!=='default'){const f='table-'+t;pimg(f,()=>{HR.style.setProperty('--tbl','url('+MEDIA+f+'.webp)');HR.classList.add('tbl','tbl-u')})}}}catch(e){}}})();
// deck piles: goods deck at the end of the market row, djinn deck at the end of the djinn row, items deck when the Crafters play
function asDecks(){if(!G||G.over)return;const back=(f,n,lbl)=>`<div class="deckback" data-help aria-label="${lbl}: ${n} left"><i style="background-image:url(media/${f}.webp)"></i><b>${n}</b></div>`;
  const mr=document.querySelector('#mkt .mrow');if(mr&&!mr.querySelector('.deckback'))mr.insertAdjacentHTML('beforeend',back('back-default',G.rdeck.length,'Goods deck'));
  const dr=document.querySelector('#mkt .drow');if(dr&&!dr.querySelector('.deckback')){dr.insertAdjacentHTML('beforeend',back('back-lamp',G.djDeck.length,'Djinn deck')+(G.ex&&G.ex.artisans?back('back-copper',(G.items||[]).length,'Item deck'):''))}}
// the Card list drawer gets a gallery: card backs, thieves, items, pieces
function asGallery(){const b=document.getElementById('refbody');if(!b||b.querySelector('.asgal'))return;
  const th=typeof THIEVES!=='undefined'?Object.keys(THIEVES).map(k=>`<figure><img src="media/thief-${k}.webp" alt=""><figcaption>${esc(THIEVES[k].n.replace(/^The /,''))}</figcaption></figure>`).join(''):'';
  const it=Object.keys(ITEM_IMG).map(k=>`<figure><img src="media/${ITEM_IMG[k]}" alt=""><figcaption>${esc(k)}</figcaption></figure>`).join('');
  b.insertAdjacentHTML('beforeend',`<section class="asgal"><h4>Card backs</h4><div class="asrow"><figure><img src="media/back-default.webp" alt=""><figcaption>Goods</figcaption></figure><figure><img src="media/back-lamp.webp" alt=""><figcaption>Djinns</figcaption></figure><figure><img src="media/back-copper.webp" alt=""><figcaption>Items</figcaption></figure></div>${th?'<h4>Cutpurses</h4><div class="asrow">'+th+'</div>':''}<h4>Items</h4><div class="asrow">${it}</div><h4>Pieces</h4><div class="asrow show3" id="asshow3"></div></section>`);if(typeof m3Gallery==='function')m3Gallery(document.getElementById('asshow3'))}
(function(){const o=render;render=function(){o.apply(this,arguments);try{asDecks()}catch(e){console.error(e)}}})();
(function(){const o=GX.onShow;GX.onShow=function(id){if(o)o.apply(this,arguments);if(id==='refd')setTimeout(()=>{try{asGallery()}catch(e){console.error(e)}},60)}})();
